Method.Implementation:
	Set tSC= $$$OK
 	///Get the Filename from the input stream
	Set tSource = pInput.Attributes("Filename")

	$$$TRACE("OnProcessInput: "_tSource)


	///Wrap the Stream object to StreamContainer	
	set pInput = $classmethod(..#CONTAINERCLASS,"%New",pInput)
	/// If the adapter has a value for ArchivePath, send async; otherwise send synchronously
	/// to ensure that we don't return to the Adapter and let it delete the file before the
	/// target Config Item is finished processing it. 
	Set tWorkArchive=(""'=..Adapter.ArchivePath) 

	//Inbound Journal
	if (..JournalIncomingData) {
		Set tSC=..JournalData(pInput, "Inbound")
	}

	Set currentDate = $ZDATETIME($ZTIMESTAMP,3,1,3)
	Set extractDate = $EXTRACT(currentDate,0,10)
	Set extractTime = $EXTRACT(currentDate,12,$LENGTH(currentDate))

	do ..valueToBeReplaced.SetAt(tSource,"%f")
	do ..valueToBeReplaced.SetAt(extractDate,"%CD")
	do ..valueToBeReplaced.SetAt(extractTime,"%CT")
	do ..valueToBeReplaced.SetAt($REPLACE($ZSTRIP(extractDate_"_"_extractTime,"*W"),":","."),"%Q")
	//We are storing the current sequence number in ^ItfGlobal(<Service Name>, "CurrentSequenceNumber")
	do ..valueToBeReplaced.SetAt(^ItfGlobal(..%ConfigName, "CurrentSequenceNumber"),"%#")


	if ($$$ISOK(tSC) && ""'=..RegexFileFilter) { // If RegexFileFilter is not empty
		if $Match(tSource,..RegexFileFilter) {
			$$$TRACE(tSource_" matches regex filter "_..RegexFileFilter_" we will process this file.")
		}
		else {
			$$$TRACE(tSource_" does not match regex filter "_..RegexFileFilter_" we will not process this file.")
			Quit $$$OK
		}
	}
	else {
		$$$TRACE("No RegexFileFilter specified; regex filter will not be applied.")
	}

	//Note: the following line is intended to skip this block if the ActionOnSourceFile field is empty, This is the intended behavior
	if ($$$ISOK(tSC) && (""'=..ActionOnSourceFile)){
		if ("DELETE"=$ZStrip(..ActionOnSourceFile,"<>W")){  //If we want to delete the source file
				If ..Adapter.delete(tSource,..Adapter.FilePath) {
					$$$sysTRACE("IHC.ITF.ITFCOMMON.FTP.Service.PassthroughService1: Deleted '"_tSource_" from FTP server after successful processing")
				} Else {
					Do ..Adapter.disconnectOnNetErr(,1)
					If '..Adapter.Connected Set tSC=$$$ERROR($$$EnsErrGeneral,"Failed to delete '"_tSource_" from FTP server after successful processing after successful processing - "_..Adapter.FTP.ReturnCode_":"_..Adapter.FTP.ReturnMessage)  Quit
					$$$LOGWARNING("IHC.ITF.ITFCOMMON.FTP.Service.PassthroughService1: Failed to delete '"_tSource_" from FTP server after successful processing after successful processing - "_..Adapter.FTP.ReturnCode_":"_..Adapter.FTP.ReturnMessage)
					Set tSC=$$$ERROR("ITFCOMMON:10101","Error deleting source file: "_..Adapter.FilePath_"/"_tSource_"; ATTEMPTED NEW NAME: "_UpdatedActionOnSourceFile_". Make sure the specified directory name is visible and writable.")
				}	
		}
	}
	//The following two conditionals only worked sometimes if combined into one conditional
	if ("DELETE"'=$ZStrip(..ActionOnSourceFile,"<>W")) {
	if ($$$ISOK(tSC) && (""'=..ActionOnSourceFile)){
			Set UpdatedActionOnSourceFile = ..replaceWithParticularFormat(..ActionOnSourceFile)
			$$$TRACE("Moving source file to "_..ActionOnSourceFile_".")
			Set renameResults = ..Adapter.rename(tSource,UpdatedActionOnSourceFile,..Adapter.FilePath)
			if (renameResults = 0) {
				Set tSC=$$$ERROR("ITFCOMMON:10101","Error renaming source file; ORIGINAL NAME: "_..Adapter.FilePath_"/"_tSource_"; ATTEMPTED NEW NAME: "_UpdatedActionOnSourceFile_". Make sure the specified directory name is visible and writable.")
			}
		}
	}

	//Send to outbound components
	if $$$ISOK(tSC){
	Set numTargets = $L(..TargetConfigNames,",")
	For iTarget=1:1:numTargets
		{
		Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W")
			If tWorkArchive {			
				Set tSC=..SendRequestAsync(tOneTarget,pInput)					
			}		
			Else {
				#; If not archiving send Sync to avoid Adapter deleting file before Operation gets it
				Set tSC=..SendRequestSync(tOneTarget,pInput)
			}			 
		}
	}

	//Outbound Journal
	If ($$$ISOK(tSC) && (..JournalOutgoingData)) {
		Set tSC=..JournalData(pInput, "Outbound")
	}	

	//Sending Email
	If $$$ISOK(tSC)
	{
		$$$TRACE("Sending alert for successful file transfer.")
		//Replace the respective values in the Email subject and the body like Filename, Date / Time received 
		Set updatedSuccessEmailSubject = ..replaceWithParticularFormat(..SuccessEmailSubject)
		Set updatedSuccessEmailbody = ..replaceWithParticularFormat(..SucessEmailBody)
		do ..ItfSendEmailOnSuccess(updatedSuccessEmailSubject, updatedSuccessEmailbody)
	}
	Else	
	{
		$$$TRACE("Sending failure email")
		Set updatedFailureEmailSubject = ..replaceWithParticularFormat(..FailureEmailSubject)
		Set updatedFailureEmailbody = ..replaceWithParticularFormat(..FailureEmailBody)
		do ..ItfSendEmailOnError(updatedFailureEmailSubject, updatedFailureEmailbody)
		//Disable the service
		Job ##class(Ens.Director).EnableConfigItem(..%ConfigName,0,1)
	}

	do ..IncrementSequenceNumber()
	Quit tSC

$$$TRACE("..ResetSequenceOnRestart="_..ResetSequenceOnRestart)
//If we are resetting the sequence number because the user wants us to or one is not configured
if ((..ResetSequenceOnRestart) || ($DATA(^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")) = "0")) {
	//If there is a configured starting sequence number, replace the current number with it, or use the default
	if (""'=..StartingSequenceNumber) {
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..StartingSequenceNumber
		$$$TRACE("Replacing sequence number with starting sequence number: "_^ItfGlobal(..%ConfigName, "CurrentSequenceNumber"))
	}
	//If there is no configured starting sequence number, use a default
	else {
		$$$TRACE("No sequence numbers defined; setting to a default of 1")
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")=	"1"
	}
}
else {
	$$$TRACE("CurrentSequenceNumber is "_^ItfGlobal(..%ConfigName, "CurrentSequenceNumber")_" and ResetSequenceOnRestart is disabled. Sequence number will not be reset")
}
Do ..VerifySequenceNumber()


if ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") < ..MinimumSequenceNumber //If sequence number is too low
{
	if ..SequenceIncrement < 0  { //If sequence number is too low and is descending, reset to maximum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MaximumSequenceNumber
		$$$TRACE("Sequence number has descended to below minimum value. Wrapping back to maximum value: "_..MaximumSequenceNumber)
	}
	if ..SequenceIncrement > 0 { //If sequence number is ascending, move to minimum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MinimumSequenceNumber
		$$$TRACE("Sequence number is beneath its minimum value.  Setting to minimum value: "_..MinimumSequenceNumber)
	}
}

if ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") > ..MaximumSequenceNumber //If sequence number is too high
{
	if ..SequenceIncrement < 0  {//If sequence number is too high and descending, set to maximum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MaximumSequenceNumber
		$$$TRACE("Sequence number is above maximum value, but descending. Setting to maximum value: "_..MaximumSequenceNumber)
	}
	if ..SequenceIncrement > 0 {// If sequence number is too high and ascending, reset to minimum
		Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = ..MinimumSequenceNumber
		$$$TRACE("Sequence number has ascended to above maximum value.  Wrapping back to minimum value: "_..MinimumSequenceNumber)
	}
}
if ..MinimumSequenceNumber > ..MaximumSequenceNumber //If the minimum and maximum violate each other
{
	$$$TRACE("MinimumSequnceNumber is greater than the MaximumSequnceNumber; setting CurrentSequenceNumber to zero.")
 	Set ^ItfGlobal(..%ConfigName, "CurrentSequenceNumber") = 0
}

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
